package org.louis.ebnfcompiler;

import java.util.Arrays;

public class Main {
    private final static String usage = "Usage: java -jar ebnfcompiler.jar <input-file> [--dump-lexing] [--dump-parsing] [--run-semantic-analysis] [--pretty-print] [--export-pretty-print-to <output-file>] [--print-graphviz] [--export-graphviz-to <output-file>] [--help]";
    private final static String detail = """
            input-file: The path to the EBNF file to compile
            --dump-lexing: Dump the tokens generated by the lexer
            --run-semantic-analysis: Run semantic analysis on the AST
            --pretty-print: Pretty print the AST
            --export-pretty-prînt--to <output-file>: Export the pretty printed AST to a plaintext file
            --print-graphviz: Print the syntax diagram generated by the visitor
            --export-graphviz-to <output-file>: Export the syntax diagram generated by the visitor to a Graphviz file (dot format)
            --help: Display this help message
    """;

    public static void main(String[] args) {
        // Parse command line arguments
        if (args.length == 0) {
            System.out.println(usage);
            System.out.println(detail);
            return;
        }

        if (Arrays.stream(args).anyMatch(arg -> arg.equalsIgnoreCase("--help"))) {
            System.out.println(usage);
            System.out.println(detail);
            return;
        }

        // Parse input file
        String sourceCodeFilename = args[0];
        if (!sourceCodeFilename.endsWith(".ebnf")) {
            System.out.println("[!] Error: Input file must be an EBNF file");
            return;
        }

        // Parse command line arguments
        if (args.length == 1) {
            System.out.println("[!] Error: No command specified");
            System.out.println(usage);
            return;
        }

        // Default values
        boolean dumpLexing = false;
        boolean prettyPrint = false;
        String prettyPrintOutputFilename = null;
        boolean printGraphviz = false;
        String graphvizOutputFilename = null;
        boolean runSemanticAnalysis = false;

        for (int i = 1; i < args.length; i++) {
            switch (args[i]) {
                case "--dump-lexing":
                    dumpLexing = true;
                    break;
                case "--run-semantic-analysis":
                    runSemanticAnalysis = true;
                    break;
                case "--pretty-print":
                    prettyPrint = true;
                    break;
                case "--export-pretty-print-to":
                    if (++i >= args.length) {
                        System.out.println("[!] Error: Missing argument for --export-pretty-print-to");
                        return;
                    }
                    prettyPrintOutputFilename = args[i];
                    break;
                case "--print-graphviz":
                    printGraphviz = true;
                    break;
                case "--export-graphviz-to":
                    if (++i >= args.length) {
                        System.out.println("[!] Error: Missing argument for --export-graphviz-to");
                        return;
                    }
                    graphvizOutputFilename = args[i];
                    break;
                default:
                    System.out.println("[!] Error: Unknown command: " + args[i]);
                    return;
            }
        }

        // Run the compiler with the specified options
        Compiler compiler = new Compiler(sourceCodeFilename);
        compiler.compile(dumpLexing, runSemanticAnalysis, prettyPrint, prettyPrintOutputFilename, printGraphviz, graphvizOutputFilename);
    }
}